def compute(vars):
    old_value = vars["v1"]
    new_value = vars["v2"]
    difference = new_value - old_value

    return {
        "value": difference,
        "trace": {
            "old_value": old_value,
            "new_value": new_value,
            "difference": difference,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
